#include <zephyr/drivers/flash.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/util.h>
#include <string.h>

#define DT_DRV_COMPAT zephyr_mock_flash

struct mock_flash_data {
	uint8_t *flash_buf;
	size_t flash_size;
	uint32_t erase_value;
	struct k_sem lock;
};

static int mock_flash_read(const struct device *dev, off_t offset, void *data, size_t len)
{
	struct mock_flash_data *dev_data = dev->data;

	k_sem_take(&dev_data->lock, K_FOREVER);

	if (offset < 0 || offset + len > dev_data->flash_size) {
		k_sem_give(&dev_data->lock);
		return -EINVAL;
	}

	memcpy(data, dev_data->flash_buf + offset, len);

	k_sem_give(&dev_data->lock);

	return 0;
}

static int mock_flash_write(const struct device *dev, off_t offset, const void *data, size_t len)
{
	struct mock_flash_data *dev_data = dev->data;

	k_sem_take(&dev_data->lock, K_FOREVER);

	if (offset < 0 || offset + len > dev_data->flash_size) {
		k_sem_give(&dev_data->lock);
		return -EINVAL;
	}

	memcpy(dev_data->flash_buf + offset, data, len);

	k_sem_give(&dev_data->lock);

	return 0;
}

static int mock_flash_erase(const struct device *dev, off_t offset, size_t size)
{
	struct mock_flash_data *dev_data = dev->data;

	k_sem_take(&dev_data->lock, K_FOREVER);

	if (offset < 0 || offset + size > dev_data->flash_size) {
		k_sem_give(&dev_data->lock);
		return -EINVAL;
	}

	memset(dev_data->flash_buf + offset, dev_data->erase_value, size);

	k_sem_give(&dev_data->lock);

	return 0;
}

static const struct flash_parameters *mock_flash_get_parameters(const struct device *dev)
{
	static const struct flash_parameters params = {
		.write_block_size = 1,
		.erase_value = 0xFF,
	};

	return &params;
}

static void mock_flash_page_layout(const struct device *dev, const struct flash_pages_layout **layout, size_t *layout_size)
{
	struct mock_flash_data *dev_data = dev->data;
	static struct flash_pages_layout mock_layout;

	mock_layout.pages_count = 1;
	mock_layout.pages_size = dev_data->flash_size;

	*layout = &mock_layout;
	*layout_size = 1;
}

static const struct flash_driver_api mock_flash_api = {
	.read = mock_flash_read,
	.write = mock_flash_write,
	.erase = mock_flash_erase,
	.get_parameters = mock_flash_get_parameters,
	.page_layout = mock_flash_page_layout,
};

#define MOCK_FLASH_INIT(inst) \
	static uint8_t mock_flash_buf_##inst[DT_INST_PROP(inst, size)]; \
	static struct mock_flash_data mock_flash_data_##inst = { \
		.flash_buf = mock_flash_buf_##inst, \
		.flash_size = DT_INST_PROP(inst, size), \
		.erase_value = DT_INST_PROP(inst, erase_value), \
		.lock = K_SEM_INITIALIZER(mock_flash_data_##inst.lock, 1, 1), \
	}; \
	DEVICE_DT_INST_DEFINE(inst, NULL, NULL, \
		&mock_flash_data_##inst, NULL, POST_KERNEL, \
		CONFIG_FLASH_INIT_PRIORITY, &mock_flash_api);

DT_INST_FOREACH_STATUS_OKAY(MOCK_FLASH_INIT)
